import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { useState } from 'react';

interface ScanResult { score: number; missing: string[]; matched: string[] };

export const useResumeScanner = () => {
  const [result, setResult] = useState<ScanResult | null>(null);
  const [loading, setLoading] = useState(false);

  const scanResume = async (file: File, jobDescription: string) => {
    setLoading(true);
    const formData = new FormData();
    formData.append('resume', file);
    formData.append('jobDescription', jobDescription);

    try {
      const response = await fetch('/api/scan', {
        method: 'POST',
        body: formData,
      });
      const data = await response.json();
      setResult(data);
    } catch (error) {
      console.error('Scan failed', error);
    } finally {
      setLoading(false);
    }
  };

  return { scanResume, result, loading };
};

import { Doughnut } from 'react-chartjs-2';
import { Chart as ChartJS, ArcElement, Tooltip } from 'chart.js';

ChartJS.register(ArcElement, Tooltip);

export const MatchScoreGauge = ({ score }: { score: number }) => {
  const data = {
    datasets: [{
      data: [score, 100 - score],
      backgroundColor: [score > 70 ? '#22c55e' : '#eab308', '#e5e7eb'],
      borderWidth: 0,
      circumference: 180,
      rotation: -90,
    }]
  };

  return (
    <div className="relative w-48 h-24">
      <Doughnut data={data} options={{ responsive: true, maintainAspectRatio: false }} />
      <div className="absolute bottom-0 left-0 right-0 text-center font-bold text-2xl">{score}%</div>
    </div>
  );
};
